from shapely.geometry import Polygon, box
from shapely.ops import unary_union
geom_results=[]
def clip_positive(points,values):
 result=[]
 for index in range(len(points)):
  previous=(index-1)%len(points); aa=points[previous]; bb=points[index]; va=values[previous]; vb=values[index]
  if (va>1e-10)!=(vb>1e-10): result.append(aa+(bb-aa)*va/(va-vb))
  if vb>1e-10: result.append(bb)
 return np.array(result)
for region_index,group in enumerate(groups):
 points=np.unique(tv[group].reshape(-1,3),axis=0); normal=normals[group[0]]
 for camera in cameras['views']:
  view=np.array(camera['view_matrix']); projection=np.array(camera['projection_matrix']); direction=np.array(camera['direction_rational'],dtype=float); direction/=np.linalg.norm(direction)
  facing=float(normal@direction); rec={'region':region_index,'view':camera['name'],'normal_dot_to_camera':facing}
  if facing<=1e-10:
   rec['status']='back_facing' if facing< -1e-10 else 'edge_on'; geom_results.append(rec); continue
  transform=projection@view
  projected=np.c_[points,np.ones(len(points))]@transform.T
  region_polygon=Polygon(projected[:,:2]).convex_hull
  # Region's plane depth is affine in projected x,y.
  coeff=np.linalg.lstsq(np.c_[projected[:,:2],np.ones(len(points))],projected[:,2],rcond=None)[0]
  blockers=[]; by_object={}
  for obj in data['objects']:
   objpts=np.c_[np.array(obj['vertices']),np.ones(len(obj['vertices']))]@transform.T
   pieces=[]
   for local_idx,triangle in enumerate(obj['triangles']):
    if obj['name']==target['name'] and local_idx in group: continue
    tri=objpts[triangle,:3]; delta=np.c_[tri[:,:2],np.ones(3)]@coeff-tri[:,2]
    clipped=clip_positive(tri,delta)
    if len(clipped)<3: continue
    poly=Polygon(clipped[:,:2])
    if poly.area<1e-15: continue
    intersection=region_polygon.intersection(poly)
    if intersection.area>1e-14: pieces.append(intersection)
   if pieces:
    combined=unary_union(pieces); by_object[obj['name']]=combined.area/region_polygon.area; blockers.append(combined)
  hidden=unary_union(blockers).area if blockers else 0
  rec.update(projected_area=region_polygon.area,occluded_fraction=hidden/region_polygon.area,occluders=by_object,inside_frustum=bool(np.all(np.abs(projected[:,:3])<=1+1e-10)),status='occluded' if hidden>1e-12 else 'unoccluded')
  geom_results.append(rec)
print(geom_results)
