for index,camera in enumerate(cameras['views'],1):
 ref=f'native-image-{index:03d}'; frame=buffers[ref]; ids=frame['triangle_ids']; rgb=frame['color'].astype(float)
 for region_index,group in enumerate(groups):
  mask=(ids>=5634+min(group))&(ids<=5634+max(group)); contrast=np.zeros(mask.shape,dtype=bool); boundary=np.zeros(mask.shape,dtype=bool)
  for row_shift,col_shift in [(1,0),(-1,0),(0,1),(0,-1)]:
   neighbor=np.roll(mask,(row_shift,col_shift),(0,1)); colors=np.roll(rgb,(row_shift,col_shift),(0,1)); valid=np.ones(mask.shape,dtype=bool)
   if row_shift==1: valid[0,:]=False
